import{_ as t,o as e,c as i,ag as l}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"保留数据后重新安装","description":"在原 Ubuntu 24 服务器保留数据后，用完整原安装包重新安装，并用原账号核对结果。","frontmatter":{"title":"保留数据后重新安装","description":"在原 Ubuntu 24 服务器保留数据后，用完整原安装包重新安装，并用原账号核对结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/reinstall.md","filePath":"zh/安装运维/保留数据后重新安装.md"}'),r={name:"zh/installation/reinstall.md"};function n(o,a,s,d,h,p){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="保留数据后重新安装" tabindex="-1">保留数据后重新安装 <a class="header-anchor" href="#保留数据后重新安装" aria-label="Permalink to &quot;保留数据后重新安装&quot;">​</a></h1><p>本页适用于此前选择了<strong>保留数据卸载</strong>，现在要在<strong>原 Ubuntu 24 服务器</strong>重新安装 InduFrame v1.0 的情况，其他系统尚未测试。</p><p>你需要原来的完整安装包、原来的数据和原账号。这个流程不用于换服务器、重装操作系统或跨版本升级，也不能代替备份还原。</p><h2 id="开始前确认材料还在" tabindex="-1">开始前确认材料还在 <a class="header-anchor" href="#开始前确认材料还在" aria-label="Permalink to &quot;开始前确认材料还在&quot;">​</a></h2><ul><li>[ ] 原服务器没有重装系统，原运行环境仍在。</li><li>[ ] 原数据和磁盘仍在，未被删除、替换或移走。</li><li>[ ] 保留了上次成功安装的<strong>完整原安装包</strong>。</li><li>[ ] 原平台超级管理员、原组织管理员的账号和密码仍可用。</li><li>[ ] 上次终端明确提示保留数据卸载成功，没有清理失败或未完成。</li><li>[ ] 卸载留下的凭据和记录没有被手工移动或删除。</li></ul><p>不确定任何一项时，先请维护人员核实。也重新检查<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>中的磁盘余量和网络条件。</p><h2 id="_1-用原安装包启动向导" tabindex="-1">1. 用原安装包启动向导 <a class="header-anchor" href="#_1-用原安装包启动向导" aria-label="Permalink to &quot;1. 用原安装包启动向导&quot;">​</a></h2><p>在原服务器终端进入完整原安装包文件夹，执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>需要时输入服务器账号的系统密码。保留数据卸载会清理部分安装设置，因此向导会再次询问安装位置、地址、端口、证书和管理员信息。</p><h2 id="_2-重新填写安装信息" tabindex="-1">2. 重新填写安装信息 <a class="header-anchor" href="#_2-重新填写安装信息" aria-label="Permalink to &quot;2. 重新填写安装信息&quot;">​</a></h2><p>建议沿用原来的安装位置和访问设置，按<a href="/induframe-docs/zh/installation/install.html">安装中心</a>完成向导。</p><table tabindex="0"><thead><tr><th>要注意什么</th><th>怎样处理</th></tr></thead><tbody><tr><td>程序位置</td><td>核对原位置，默认 <code>/opt</code> 对应程序目录 <code>/opt/induframe</code></td></tr><tr><td>地址与端口</td><td>确认原地址仍可用，保存本次打印的两个完整入口</td></tr><tr><td>证书</td><td>重新选择；使用已有证书时，重新提供文件路径</td></tr><tr><td>初始管理员密码</td><td>仍需按提示输入两次，但不会覆盖已经存在的平台管理员密码</td></tr></tbody></table><p><strong>登录时继续使用原账号和原密码。</strong> 向导再次询问初始密码，不表示可以靠重装找回原密码。忘记密码时，先处理账号问题。</p><h2 id="_3-等待完成-再打开网页" tabindex="-1">3. 等待完成，再打开网页 <a class="header-anchor" href="#_3-等待完成-再打开网页" aria-label="Permalink to &quot;3. 等待完成，再打开网页&quot;">​</a></h2><p>等到 14 个阶段完成，命令正常结束，并出现 <strong>“InduFrame 中心安装完成。”</strong>，保存两个入口和日志位置。</p><p>使用自签名证书时，本次会生成新证书，浏览器可能再次提醒不受信任，请维护人员核对后处理。</p><p>若提示原数据或凭据缺失、卸载未完成，停止并保留现场，不要创建同名空数据绕过检查。</p><h2 id="_4-用原账号核对" tabindex="-1">4. 用原账号核对 <a class="header-anchor" href="#_4-用原账号核对" aria-label="Permalink to &quot;4. 用原账号核对&quot;">​</a></h2><ol><li>打开本次管理入口，以<strong>原平台超级管理员</strong>登录，确认原组织仍在。</li><li>打开公共入口，选择原组织，以<strong>原组织管理员</strong>的用户名和密码登录。</li><li>打开工程管理，确认需要的工程仍在，刷新后再检查。</li><li>按<a href="/induframe-docs/zh/installation/verify.html">确认安装成功</a>检查访问和退出。</li><li>请业务负责人核对工程数据及需要的采集、计算、报警等功能，再恢复使用。</li></ol><p>原组织完成过首次设置时，不需要再重置默认组织管理员密码。能登录只是基本访问恢复，还需核对实际业务。</p><h2 id="没有成功时怎么办" tabindex="-1">没有成功时怎么办 <a class="header-anchor" href="#没有成功时怎么办" aria-label="Permalink to &quot;没有成功时怎么办&quot;">​</a></h2><p>保留安装阶段、完整提示和日志路径，同时保留原数据与卸载留下的资料，联系维护人员。不要反复重装、删除原数据，或改选删除数据卸载来消除提示。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>确认基本访问和所需业务都正常后再恢复使用。日常操作见<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>；需要再次停用时，先核对<a href="/induframe-docs/zh/installation/uninstall.html">卸载平台</a>的影响范围。</p>',25)])])}const _=t(r,[["render",n]]);export{u as __pageData,_ as default};
